package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.json.JsonReadContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TokenBuffer.writeNumber(double d).
 */
public class TokenBuffer_writeNumber_TriageGen0Test {

    private ObjectMapper mapper;
    private TokenBuffer tokenBuffer;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        // Initialize TokenBuffer with a codec to allow serialization/parsing verification
        tokenBuffer = new TokenBuffer(mapper);
    }

    @Test
    public void testWriteNumber_PositiveDouble() throws IOException {
        double val = 123.456;
        tokenBuffer.writeNumber(val);

        // Verify via JsonParser to ensure the token type and value are correct
        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());
        assertEquals(val, parser.getDoubleValue(), 0.0001);
    }

    @Test
    public void testWriteNumber_NegativeDouble() throws IOException {
        double val = -987.654;
        tokenBuffer.writeNumber(val);

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());
        assertEquals(val, parser.getDoubleValue(), 0.0001);
    }

    @Test
    public void testWriteNumber_Zero() throws IOException {
        double val = 0.0;
        tokenBuffer.writeNumber(val);

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());
        assertEquals(val, parser.getDoubleValue(), 0.0);
    }

    @Test
    public void testWriteNumber_Infinity() throws IOException {
        double val = Double.POSITIVE_INFINITY;
        tokenBuffer.writeNumber(val);

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());
        assertEquals(Double.POSITIVE_INFINITY, parser.getDoubleValue(), 0.0);
    }

    @Test
    public void testWriteNumber_NaN() throws IOException {
        double val = Double.NaN;
        tokenBuffer.writeNumber(val);

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());
        assertEquals(Double.NaN, parser.getDoubleValue());
    }

    @Test
    public void testWriteNumber_SmallDouble() throws IOException {
        double val = 1.23e-10;
        tokenBuffer.writeNumber(val);

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());
        assertEquals(val, parser.getDoubleValue(), 0.0);
    }

    @Test
    public void testWriteNumber_LargeDouble() throws IOException {
        double val = 1.23e10;
        tokenBuffer.writeNumber(val);

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());
        assertEquals(val, parser.getDoubleValue(), 0.0);
    }

    @Test
    public void testWriteNumber_Sequence() throws IOException {
        // Test that multiple calls append correctly
        tokenBuffer.writeNumber(1.1);
        tokenBuffer.writeNumber(2.2);

        JsonParser parser = tokenBuffer.asParser();

        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertEquals(1.1, parser.getDoubleValue(), 0.0001);

        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertEquals(2.2, parser.getDoubleValue(), 0.0001);
    }
}
